590	// Among multiple shortest paths the lexicographically smallest full name
591	// sequence wins, compared name by name in Go string order, even when child list
592	// order would suggest otherwise.
593	func TestImpactsLexicographicallySmallestShortestPath(t *testing.T) {
594		graph := map[string]*Lineage{}
595		mustRegister(t, graph, "s")
596		// Register the lexicographically larger branch first so stored child order
597		// disagrees with the expected path choice.
598		mustRegister(t, graph, "z", "s")
599		mustRegister(t, graph, "a", "s")
600		mustRegister(t, graph, "m", "z", "a")
601	
602		impacts, err := Impacts(graph, "s")
603		if err != nil {
604			t.Fatalf("Impacts(s): %v", err)
605		}
606		assertImpact(t, impacts, "m", 2, []string{"s", "a", "m"})
607	
608		// Tie decided at the final hop: both x routes to n have equal length.
