1239			}
1240			if up.Distance != wantDistance {
1241				t.Errorf("upstream %s distance = %d, want %d", name, up.Distance, wantDistance)
1242			}
1243			if !sameStrings(up.Path, wantPath) {
1244				t.Errorf("upstream %s path = %v, want %v", name, up.Path, wantPath)
1245			}
1246			return
1247		}
1248		t.Fatalf("upstream %q missing from %v", name, upstreamNames(upstreams))
