86		assertEntry(t, graph, "report", []string{"b"}, nil)
87		assertConsistent(t, graph)
88	
89		// The cutoff registrations remain usable by ordinary queries.
90		if got, err := Impacts(graph, "b"); err != nil {
91			t.Fatalf("cutoff b must stay registered: %v", err)
92		} else if want := []Impact{{Dataset: "report", Distance: 1, Path: []string{"b", "report"}}}; !reflect.DeepEqual(got, want) {
93			t.Fatalf("Impacts(b) = %v, want %v", got, want)
94		}
95	}
96	
97	// The later cutoff alone does what an ordinary deep cutoff does: a and b both
98	// appear, report is dropped at b. This pins down that b disappears from the
99	// two-cutoff result purely because a blocks it, not because naming b has any
100	// special effect.
101	func TestImpactsWithCutoffsChainedLaterCutoffAloneStopsAtIt(t *testing.T) {
102		graph := buildChainedCutoffChain(t)
103	
104		impacts := mustImpactsWithCutoffs(t, graph, "source", "b")
105		want := []Impact{
106			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
107			{Dataset: "b", Distance: 2, Path: []string{"source", "a", "b"}},
108		}
109		if !reflect.DeepEqual(impacts, want) {
110			t.Fatalf("cutoff b: impacts = %v, want %v", impacts, want)
111		}
112		assertImpactOnce(t, impacts, "b", 2, []string{"source", "a", "b"})
113		if names := impactNames(impacts); slices.Contains(names, "report") {
114			t.Fatalf("report lies past cutoff b and must not appear, got %v", names)
115		}
116	}
117	
118	// Swapping the two cutoffs' input order, or repeating either name, must give
119	// the same result on the single chain.
120	func TestImpactsWithCutoffsChainedOrderAndDuplicatesInvariant(t *testing.T) {
121		graph := buildChainedCutoffChain(t)
122		want := []Impact{
123			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
124		}
125		for _, cutoffs := range [][]string{
126			{"a", "b"},
127			{"b", "a"},
128			{"a", "a", "b"},
129			{"b", "b", "a"},
130			{"a", "b", "b"},
131			{"b", "a", "b", "a"},
132		} {
133			got, err := ImpactsWithCutoffs(graph, "source", cutoffs)
134			if err != nil {
135				t.Fatalf("cutoffs %v: %v", cutoffs, err)
136			}
137			if !reflect.DeepEqual(got, want) {
138				t.Fatalf("cutoffs %v: impacts = %v, want %v", cutoffs, got, want)
139			}
140		}
141	}
142	
143	// Regression for the second lineage structure: a bypass branch reaches the
144	// later cutoff without passing the earlier one.
145	//
146	//	source -> a -> b -> report
147	//	  |                ^
148	//	  +-> c -> d ------+
149	//
150	// source derives a and c; a derives b; c derives d; b depends on a and d and
151	// derives report. With a and b both named, a stops the short branch but c and
152	// d reach b independently, so b DOES appear — exactly once, at distance 3 with
153	// path [source c d b], not at the full query's distance 2 via [source a b].
154	// Propagation still stops at b, so report is gone. A later cutoff must not be
155	// excluded merely because it sits downstream of another cutoff; it is included
156	// iff a cutoff-free route reaches it.
157	
158	// buildChainedCutoffBypass registers the chain plus the c/d bypass into b.
159	func buildChainedCutoffBypass(t *testing.T) map[string]*Lineage {
160		t.Helper()
161		return buildRegisteredGraph(t, [][]string{
162			{"source"},
163			{"a", "source"},
164			{"c", "source"},
165			{"d", "c"},
166			{"b", "a", "d"},
167			{"report", "b"},
168		})
169	}
170	
171	// The unrestricted query explains b at distance 2 through a, the shortest
172	// route; that distance and path belong to the full query alone.
173	func TestImpactsWithCutoffsBypassFullQueryBaseline(t *testing.T) {
174		graph := buildChainedCutoffBypass(t)
175		assertConsistent(t, graph)
176	
177		full := mustImpacts(t, graph, "source")
178		assertImpactOnce(t, full, "b", 2, []string{"source", "a", "b"})
179		assertImpactOnce(t, full, "report", 3, []string{"source", "a", "b", "report"})
180	}
181	
182	// With a and b named, b survives only via the cutoff-free c/d route at
183	// distance 3; the truncated distance-2 route via a is never reused. b is
184	// listed once, report past b is dropped, and results stay ordered by distance
185	// ascending and then by dataset name in Go string order.
186	func TestImpactsWithCutoffsBypassReachesLaterCutoffOnAllowedRoute(t *testing.T) {
187		graph := buildChainedCutoffBypass(t)
188		assertConsistent(t, graph)
189		before := snapshot(graph)
190	
191		impacts := mustImpactsWithCutoffs(t, graph, "source", "a", "b")
192		want := []Impact{
193			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
194			{Dataset: "c", Distance: 1, Path: []string{"source", "c"}},
195			{Dataset: "d", Distance: 2, Path: []string{"source", "c", "d"}},
196			{Dataset: "b", Distance: 3, Path: []string{"source", "c", "d", "b"}},
197		}
198		if !reflect.DeepEqual(impacts, want) {
199			t.Fatalf("cutoffs a,b: impacts = %v, want %v", impacts, want)
200		}
201		// b appears exactly once and is explained by the bypass, never by the
202		// full query's shorter a route.
203		assertImpactOnce(t, impacts, "b", 3, []string{"source", "c", "d", "b"})
204		for _, im := range impacts {
205			if slices.Contains(im.Path[:len(im.Path)-1], "a") {
206				t.Fatalf("path traverses cutoff a: %v", im.Path)
207			}
208		}
209		if names := impactNames(impacts); slices.Contains(names, "report") {
210			t.Fatalf("reaching cutoff b must still stop propagation there: report must be gone, got %v", names)
211		}
212		// Distance-ascending, name-tie-broken order.
213		if got, wantNames := impactNames(impacts), []string{"a", "c", "d", "b"}; !reflect.DeepEqual(got, wantNames) {
214			t.Fatalf("order = %v, want %v", got, wantNames)
215		}
216	
217		// Success query preserves nodes, both-direction edges and list order.
218		if !reflect.DeepEqual(snapshot(graph), before) {
219			t.Fatalf("cutoff query changed graph: before=%v after=%v", before, snapshot(graph))
220		}
221		assertEntry(t, graph, "b", []string{"a", "d"}, []string{"report"})
222		assertEntry(t, graph, "report", []string{"b"}, nil)
223		assertConsistent(t, graph)
224	
225		// A subsequent full query is unaffected: b is back to distance 2 via a.
226		full := mustImpacts(t, graph, "source")
227		assertImpactOnce(t, full, "b", 2, []string{"source", "a", "b"})
228		assertImpactOnce(t, full, "report", 3, []string{"source", "a", "b", "report"})
229	}
230	
231	// Same bypass structure: cutoff input order and repeated names must not change
232	// the result, and neither cutoff being downstream of the other changes its
233	// inclusion.
234	func TestImpactsWithCutoffsBypassOrderAndDuplicatesInvariant(t *testing.T) {
235		graph := buildChainedCutoffBypass(t)
236		want := []Impact{
237			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
238			{Dataset: "c", Distance: 1, Path: []string{"source", "c"}},
239			{Dataset: "d", Distance: 2, Path: []string{"source", "c", "d"}},
240			{Dataset: "b", Distance: 3, Path: []string{"source", "c", "d", "b"}},
241		}
242		for _, cutoffs := range [][]string{
243			{"a", "b"},
244			{"b", "a"},
245			{"a", "a", "b"},
246			{"b", "b", "a"},
247			{"b", "a", "b"},
248		} {
249			got, err := ImpactsWithCutoffs(graph, "source", cutoffs)
250			if err != nil {
251				t.Fatalf("cutoffs %v: %v", cutoffs, err)
252			}
253			if !reflect.DeepEqual(got, want) {
254				t.Fatalf("cutoffs %v: impacts = %v, want %v", cutoffs, got, want)
255			}
256		}
257	}
258	
259	// Stopping propagation is not stopping validation: every cutoff name is
260	// checked against the registry BEFORE the traversal and regardless of where
261	// propagation would stop. On the single chain, a already blocks every route
262	// (so no successful traversal could reach anything beyond it), yet an
263	// unregistered name later in the list must fail the whole query with an error
264	// naming it and nil results — the already-reachable a must not come back as a
265	// partial result.
266	func TestImpactsWithCutoffsChainedUnregisteredNameAfterTruncatingCutoff(t *testing.T) {
267		graph := buildChainedCutoffChain(t)
268		assertConsistent(t, graph)
269		before := snapshot(graph)
270	
271		for _, cutoffs := range [][]string{
272			{"a", "ghost"},
273			{"ghost", "a"},
274			{"b", "ghost"}, // first cutoff alone would succeed; the bad name still fails it all
275			{"a", "b", "ghost"},
276			{"a", "a", "ghost"},
277		} {
278			got, err := ImpactsWithCutoffs(graph, "source", cutoffs)
279			if err == nil || !strings.Contains(err.Error(), "cutoff dataset not found: ghost") {
280				t.Fatalf("cutoffs %v: want not-found cutoff error naming ghost, got %v", cutoffs, err)
281			}
282			if got != nil {
283				t.Fatalf("cutoffs %v: want nil results even though the traversal has reachable cutoffs, got %v",
284					cutoffs, got)
285			}
286		}
287	
288		// The unregistered name is exactly "ghost"; the registered cutoffs stay
289		// registered and no lineage is altered.
290		if !reflect.DeepEqual(snapshot(graph), before) {
291			t.Fatalf("failed queries changed graph: before=%v after=%v", before, snapshot(graph))
292		}
293		assertEntry(t, graph, "a", []string{"source"}, []string{"b"})
294		assertEntry(t, graph, "b", []string{"a"}, []string{"report"})
295		assertConsistent(t, graph)
296	
297		// The same rule on the bypass structure: a truncates the short branch and
298		// b is reached around it, but the trailing unregistered name still fails
299		// the whole request with nil results rather than returning a,c,d,b.
300		bypass := buildChainedCutoffBypass(t)
301		bypassBefore := snapshot(bypass)
302		got, err := ImpactsWithCutoffs(bypass, "source", []string{"a", "b", "ghost"})
303		if err == nil || !strings.Contains(err.Error(), "cutoff dataset not found: ghost") {
304			t.Fatalf("bypass: want not-found cutoff error naming ghost, got %v", err)
305		}
306		if got != nil {
307			t.Fatalf("bypass: want nil results despite reachable cutoffs a and b, got %v", got)
308		}
309		if !reflect.DeepEqual(snapshot(bypass), bypassBefore) {
310			t.Fatalf("bypass: failed query changed graph: before=%v after=%v", bypassBefore, snapshot(bypass))
311		}
312	}
313	
314	// A failed whole-request validation leaves the very next valid query
315	// unaffected, in both lineage structures.
316	func TestImpactsWithCutoffsChainedFailedValidationDoesNotPoisonLaterQuery(t *testing.T) {
317		chain := buildChainedCutoffChain(t)
318		if _, err := ImpactsWithCutoffs(chain, "source", []string{"a", "missing"}); err == nil {
319			t.Fatal("expected not-found cutoff error")
320		}
321		chainWant := []Impact{{Dataset: "a", Distance: 1, Path: []string{"source", "a"}}}
322		if got := mustImpactsWithCutoffs(t, chain, "source", "a", "b"); !reflect.DeepEqual(got, chainWant) {
323			t.Fatalf("chain valid query after failed one = %v, want %v", got, chainWant)
324		}
325	
326		bypass := buildChainedCutoffBypass(t)
327		if _, err := ImpactsWithCutoffs(bypass, "source", []string{"b", "missing"}); err == nil {
328			t.Fatal("expected not-found cutoff error")
329		}
330		bypassWant := []Impact{
331			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
332			{Dataset: "c", Distance: 1, Path: []string{"source", "c"}},
333			{Dataset: "d", Distance: 2, Path: []string{"source", "c", "d"}},
334			{Dataset: "b", Distance: 3, Path: []string{"source", "c", "d", "b"}},
335		}
336		if got := mustImpactsWithCutoffs(t, bypass, "source", "b", "a"); !reflect.DeepEqual(got, bypassWant) {
337			t.Fatalf("bypass valid query after failed one = %v, want %v", got, bypassWant)
338		}
339	}
340	
341	// Existing no-cutoff behavior is unchanged by the chained-cutoff guarantees:
342	// the nil and empty cutoff forms stay exactly the full Impacts query on both
343	// structures, including the short a route and report.
344	func TestImpactsWithCutoffsChainedEmptyStillEqualsFull(t *testing.T) {
345		for _, build := range []func(t *testing.T) map[string]*Lineage{
346			buildChainedCutoffChain,
347			buildChainedCutoffBypass,
348		} {
349			graph := build(t)
350			full := mustImpacts(t, graph, "source")
351			nilCut := mustImpactsWithCutoffs(t, graph, "source")
352			if !reflect.DeepEqual(nilCut, full) {
353				t.Fatalf("nil cutoffs = %v, want full Impacts %v", nilCut, full)
354			}
355			empty, err := ImpactsWithCutoffs(graph, "source", []string{})
356			if err != nil || !reflect.DeepEqual(empty, full) {
357				t.Fatalf("empty cutoffs = %v, %v; want full Impacts %v", empty, err, full)
358			}
359		}
360	}
